-- rng_test.lua - reference values generated by the real rng.js
-- (`node -e "..."`, see the conversation this port was built in) and
-- cross-checked byte-for-byte against this Lua port's own output before
-- being hardcoded here as the permanent regression fixture.

local T = require("testing")
local rng_mod = require("rng")
local Rng = rng_mod.Rng
local hashStringToSeed = rng_mod.hashStringToSeed

local CASES = {
	{
		seed = "celeste-pcg", hash = 1216906967,
		nexts = { 0.040852443547919, 0.31765682715923, 0.12684474629350, 0.43754110229202, 0.73681155825034, 0.19339315872639, 0.46605297503993, 0.47321073524654 },
		ints = { 4, 31, 12, 43, 73 },
	},
	{
		seed = "pmpg:topology", hash = 581609102,
		nexts = { 0.83849978609942, 0.23793484759517, 0.15751526411623, 0.79525533621199, 0.23489783867262, 0.21886310540140, 0.26784478407353, 0.16012831591070 },
		ints = { 83, 23, 15, 79, 23 },
	},
	{
		seed = "a-00", hash = 3578361355,
		nexts = { 0.51030444470234, 0.97485823393799, 0.34873848734424, 0.18990671099164, 0.09000451839529, 0.16568471095525, 0.07233272609301, 0.61987325828522 },
		ints = { 51, 97, 34, 18, 9 },
	},
	{
		seed = 42,
		nexts = { 0.60110375192016, 0.44829055899754, 0.85246579349041, 0.66973404143937, 0.17481389874592, 0.52659254218452, 0.27322799433023, 0.62474465393461 },
		ints = { 60, 44, 85, 66, 17 },
	},
	{
		seed = 0, -- the "seed 0 falls back to 1" edge case
		nexts = { 0.62707394058816, 0.00273572118022, 0.52744703995995, 0.98105096747167, 0.96837789821438, 0.28110350295901, 0.61283886060119, 0.72074314113706 },
		ints = { 62, 0, 52, 98, 96 },
	},
	{
		seed = "hello world", hash = 3582672807,
		nexts = { 0.79807166778482, 0.76675783400424, 0.93145388062112, 0.53707239520736, 0.88746640807949, 0.54362506675534, 0.72385079599917, 0.42874324508011 },
		ints = { 79, 76, 93, 53, 88 },
	},
	{
		seed = "", hash = 2166136261, -- empty-string seed edge case
		nexts = { 0.61124445218593, 0.49352429178543, 0.77402488351800, 0.41228611161932, 0.81226578145288, 0.05720820324495, 0.91590391821228, 0.19360002595931 },
		ints = { 61, 49, 77, 41, 81 },
	},
}

for _, c in ipairs(CASES) do
	T.test("rng: next() matches rng.js for seed " .. tostring(c.seed), function()
		if c.hash then
			T.assertEqual(hashStringToSeed(c.seed), c.hash, "hashStringToSeed")
		end
		local r = Rng.new(c.seed)
		for i, expected in ipairs(c.nexts) do
			T.assertClose(r:next(), expected, 1e-10, "next() #" .. i)
		end
	end)

	T.test("rng: int(0,99) matches rng.js for seed " .. tostring(c.seed), function()
		local r = Rng.new(c.seed)
		for i, expected in ipairs(c.ints) do
			T.assertEqual(r:int(0, 99), expected, "int() #" .. i)
		end
	end)
end

T.test("rng: pick/shuffle stay in range and use every element", function()
	local r = Rng.new("shuffle-check")
	local arr = { 10, 20, 30, 40, 50 }
	for _ = 1, 20 do
		local v = r:pick(arr)
		T.assertTrue(v == 10 or v == 20 or v == 30 or v == 40 or v == 50, "pick returned an out-of-set value")
	end
	local shuffled = r:shuffle({ 1, 2, 3, 4, 5 })
	local sum = 0
	for _, v in ipairs(shuffled) do
		sum = sum + v
	end
	T.assertEqual(sum, 15, "shuffle should preserve every element")
	T.assertEqual(#shuffled, 5, "shuffle should preserve length")
end)
